CustomField.formula:
IF(
/*If Account is Country Parent, stores Information_Governance_Rep__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Information_Governance_Rep__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's Information_Governance_Rep__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Information_Governance_Rep__c,Information_Governance_Rep__c))
